src/app/globals.css.content:
@import "tailwindcss";
@import "@fontsource-variable/inter";
:root {
  color-scheme: dark;
}
body {
  margin: 0;
  background: #0b0f19;
  color: #f5f5fa;
  font-family: Arial, Helvetica, sans-serif;
  background-image: radial-gradient(
    ellipse at 80% 0%,
    #7c3aed18,
    transparent 45%
  );
}
button,
a,
input,
select {
  -webkit-tap-highlight-color: transparent;
}
a,
button,
input,
select {
  outline-offset: 5px;
}
:focus-visible {
  outline: 2px solid #a78bfa;
}
::selection {
  background: #7c3aed;
  color: white;
}
.miniapp {
  padding-top: var(--tg-content-safe-area-inset-top, 0px);
  padding-bottom: env(safe-area-inset-bottom);
}
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

.miniapp main {
  padding-top: 16px;
}
.miniapp .catalog-hero {
  padding: 22px;
  margin-bottom: 24px;
}
.miniapp .catalog-hero > span {
  display: none;
}
.miniapp .catalog-hero h1 {
  font-size: 30px;
  margin-top: 0;
}
.miniapp .catalog-hero p {
  margin-top: 14px;
  font-size: 14px;
  line-height: 1.6;
}

.miniapp .country-heading {
  font-size: 24px;
}
.miniapp .country-deep-link {
  display: none;
}

:root {
  --surface: #101624;
  --muted: #8d99b0;
  --accent: #a28cff;
}
body {
  background: #080d17;
  background-image:
    radial-gradient(ellipse at 92% -10%, #6b4cf524, transparent 42%),
    radial-gradient(ellipse at 0% 70%, #0891b210, transparent 38%);
  font-family: Inter, Arial, Helvetica, sans-serif;
}
.web-header {
  position: sticky;
  top: 0;
  z-index: 40;
}
.category-nav {
  display: flex;
  gap: 8px;
  max-width: 1280px;
  margin: auto;
  padding: 18px 20px 0;
  overflow-x: auto;
  white-space: nowrap;
}
.category-nav a {
  padding: 9px 16px;
  border: 1px solid #ffffff0b;
  border-radius: 12px;
  color: #8d99b0;
  font-size: 13px;
  transition: background 0.2s;
}
.category-nav a:hover,
.category-nav a[aria-current="page"] {
  color: #c9baff;
  background: #8b5cf617;
  border-color: #8b5cf633;
}
.eyebrow {
  display: flex;
  align-items: center;
  gap: 9px;
  color: #b19cf1;
  font-size: 10px;
  letter-spacing: 0.2em;
  font-weight: 600;
}
.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #6ee7b7;
  box-shadow: 0 0 12px #6ee7b777;
}
.home-hero {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  align-items: center;
  gap: 30px;
  padding: 34px 0 60px;
  min-height: 460px;
}
.home-hero h1 {
  font-size: clamp(38px, 4.5vw, 64px);
  font-weight: 650;
  line-height: 1.06;
  letter-spacing: -0.045em;
  max-width: 650px;
  margin: 24px 0;
  color: #f5f2ff;
}
.hero-intro {
  color: #98a3b9;
  max-width: 490px;
  font-size: 16px;
  line-height: 1.8;
}
.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 30px;
}
.primary-button,
.secondary-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 14px 20px;
  border-radius: 13px;
  font-size: 13px;
  font-weight: 600;
  transition:
    transform 0.2s,
    background 0.2s;
}
.primary-button {
  background: linear-gradient(120deg, #9b6aff, #6949e5);
  color: #fff;
  box-shadow: 0 8px 35px #8055ed30;
}
.secondary-button {
  background: #ffffff04;
  border: 1px solid #ffffff16;
  color: #c4c9d6;
}
.primary-button:hover,
.secondary-button:hover {
  transform: translateY(-2px);
}
.hero-labels {
  display: flex;
  flex-wrap: wrap;
  gap: 19px;
  margin-top: 28px;
  color: #7e8aa3;
  font-size: 11px;
}
.hero-labels span {
  display: flex;
  align-items: center;
  gap: 7px;
}
.hero-labels b {
  color: #c4b5fd;
  font-size: 15px;
}
.hero-art {
  position: relative;
  min-height: 350px;
  display: grid;
  place-items: center;
  background: radial-gradient(circle, #7857ee20, transparent 64%);
}
.orbit {
  position: absolute;
  border: 1px solid #b4a0ff17;
  border-radius: 50%;
  width: 290px;
  height: 290px;
}
.orbit-two {
  width: 380px;
  height: 380px;
  border-style: dashed;
  transform: rotate(20deg);
}
.portal-core {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 22px;
  justify-content: center;
  width: 180px;
  height: 180px;
  border: 1px solid #b5a2ff40;
  border-radius: 48px;
  background: linear-gradient(150deg, #a68aff25, #141a2b);
  color: #d0bdff;
  box-shadow:
    0 0 65px #8a5aff22,
    inset 0 1px 0 #ffffff20;
  transform: rotate(-8deg);
}
.portal-core span {
  font-size: 9px;
  letter-spacing: 0.16em;
}
.orbit-icon {
  position: absolute;
  width: 82px;
  height: 82px;
  display: grid;
  place-items: center;
  border-radius: 22px;
  border: 1px solid #ffffff1c;
  background: #141b2be6;
  box-shadow: 0 15px 45px #0005;
  backdrop-filter: blur(12px);
}
.orbit-telegram {
  left: 12%;
  top: 12%;
  transform: rotate(8deg);
}
.orbit-steam {
  right: 5%;
  top: 35%;
  transform: rotate(-10deg);
}
.orbit-social {
  bottom: 0;
  left: 28%;
  color: #c4b5fd;
  transform: rotate(8deg);
}
.orbit-label {
  position: absolute;
  bottom: -15px;
  right: 6%;
  font-size: 8px;
  letter-spacing: 0.25em;
  color: #646f87;
}
.section-space {
  margin: 0 0 54px;
  scroll-margin-top: 105px;
}
.section-heading {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 24px;
}
.section-heading h2,
.journey-panel h2 {
  font-size: 26px;
  font-weight: 600;
  letter-spacing: -0.03em;
  margin-top: 9px;
}
.section-heading > p {
  color: #7e8aa3;
  font-size: 13px;
}
.category-tiles {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 16px;
}
.category-tile {
  overflow: hidden;
  position: relative;
  border: 1px solid #ffffff10;
  border-radius: 24px;
  background: linear-gradient(150deg, #ffffff05, #ffffff02);
  transition:
    transform 0.25s,
    border-color 0.25s;
}
.category-tile:hover {
  transform: translateY(-5px);
  border-color: #a78bfa60;
}
.tile-visual {
