/* Ambient Ribbon & Stardust background effects */
#bg-canvas {
  position: fixed;
  inset: 0;
  width: 100vw;
  height: 100vh;
  pointer-events: none;
  z-index: 0;
  opacity: 0.85;
}
.glow-spot {
  position: fixed;
  border-radius: 50%;
  filter: blur(90px);
  pointer-events: none;
  z-index: 0;
  opacity: 0.16;
  animation: pulse-ambient-glow 9s ease-in-out infinite alternate;
}
.glow-spot.spot-1 {
  width: 440px;
  height: 440px;
  top: -120px;
  right: -90px;
  background: radial-gradient(circle, #f43f5e, #8b5cf6 60%, transparent 80%);
}
.glow-spot.spot-2 {
  width: 380px;
  height: 380px;
  bottom: 40px;
  left: -80px;
  background: radial-gradient(circle, #a855f7, #3b82f6 60%, transparent 80%);
  animation-delay: -4.5s;
}
@keyframes pulse-ambient-glow {
  0% {
    transform: scale(0.9) translate(0, 0);
    opacity: 0.12;
  }
  100% {
    transform: scale(1.15) translate(20px, 30px);
    opacity: 0.22;
  }
}
.catalog-hero {
  background:
    radial-gradient(ellipse at right, #8658e71b, transparent 70%), #11182755 !important;
  border-color: #ffffff10 !important;
}
@media (max-width: 1000px) {
  .category-tiles {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .hero-art {
    transform: scale(0.8);
  }
  .journey-panel {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 640px) {
  .home-hero {
    grid-template-columns: 1fr;
    padding: 0 0 30px;
    min-height: auto;
    gap: 0;
  }
  .home-hero h1 {
    font-size: 40px;
    margin: 20px 0;
  }
  .hero-art {
    display: none;
  }
  .hero-intro {
    font-size: 14px;
  }
  .hero-actions {
    margin-top: 23px;
  }
  .hero-labels {
    margin-top: 22px;
  }
  .section-heading h2 {
    font-size: 23px;
  }
  .section-space {
    margin-bottom: 35px;
  }
  .category-tiles {
    gap: 12px;
  }
  .category-tile {
    border-radius: 20px;
  }
  .tile-visual {
    height: 100px;
  }
  .tile-logo {
    width: 50px;
    height: 50px;
  }
  .tile-body {
    padding: 5px 15px 16px;
  }
  .tile-body h3 {
    font-size: 14px;
  }
  .tile-body p {
    font-size: 11px;
    min-height: 56px;
  }
  .journey-panel {
    padding: 22px;
  }
  .journey-steps {
    grid-template-columns: 1fr;
    gap: 15px;
  }
  .journey-steps > div {
    display: flex;
    gap: 14px;
    align-items: center;
  }
  .journey-steps p {
    margin: 0;
  }
  .category-nav {
    padding-top: 12px;
  }
  .miniapp .home-hero h1 {
    font-size: 35px;
  }
