.verification-back {
  font-size: 13px;
  color: #b9a4f3;
  display: inline-flex;
  margin-top: 15px;
  margin-bottom: 24px;
}
.verification-detail {
  display: grid;
  grid-template-columns: 1fr 1.15fr;
  gap: 60px;
  align-items: center;
  border: 1px solid #ffffff12;
  border-radius: 26px;
  background: linear-gradient(135deg, #ffffff04, #ffffff01);
  padding: 40px;
  margin-bottom: 30px;
}
.verification-detail-art {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 380px;
  border-radius: 22px;
  background:
    radial-gradient(ellipse at center, #a78bfa14, transparent 70%), #0b101e;
  position: relative;
  border: 1px solid #ffffff08;
}
.verification-detail-brand {
  font-size: 12px;
  letter-spacing: 0.15em;
  color: #8293ac;
}
.verification-detail-manual {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #b49ded;
  font-size: 12px;
  margin-top: 35px;
}
.verification-detail-content h1 {
  font-size: clamp(26px, 3vw, 42px);
  font-weight: 650;
  letter-spacing: -0.03em;
  line-height: 1.2;
  margin: 18px 0;
}
.verification-detail-content > p:not(.eyebrow) {
  font-size: 13px;
  line-height: 1.8;
  color: #8d9ab0;
}
.verification-detail-price {
  margin: 24px 0;
  padding: 20px 0;
  border-top: 1px solid #ffffff10;
  border-bottom: 1px solid #ffffff10;
}
.verification-detail-price > span {
  display: block;
  font-size: 11px;
  color: #8d9ab0;
  margin-bottom: 9px;
}
.verification-detail-price > span.flex {
  color: inherit;
}
.verification-detail-content ul {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 0;
  margin: 22px 0;
  list-style: none;
}
.verification-detail-content li {
  display: flex;
  gap: 10px;
  align-items: center;
  font-size: 12px;
  color: #a8b4c8;
}
.verification-detail-content li svg {
  color: #ae95ef;
  flex-shrink: 0;
}
.verification-detail-content .primary-button {
  margin: 22px 0 12px;
}
.verification-detail-content > p.verification-detail-note {
  font-size: 10px;
  color: #687a96;
}
.verification-tabs button:focus-visible,
.verification-card-cta:focus-visible,
.verification-back:focus-visible {
  outline: 2px solid #a78bfa;
  outline-offset: 4px;
}
@media (max-width: 1050px) {
  .verification-hero {
    gap: 30px;
  }
  .verification-hero-copy h1 {
    font-size: 48px;
  }
  .verification-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .verification-brand-tile {
    min-height: 110px;
  }
  .verification-conditions {
    flex-wrap: wrap;
  }
  .verification-detail {
    gap: 30px;
    padding: 28px;
  }
}
@media (max-width: 640px) {
  .verification-hero {
    grid-template-columns: 1fr;
    gap: 12px;
    padding: 30px 0 40px;
  }
  .verification-hero-copy h1 {
    font-size: 40px;
    max-width: 420px;
  }
  .verification-hero-copy > p:not(.eyebrow) {
    font-size: 14px;
  }
  .verification-hero-perks {
    gap: 12px;
    font-size: 10px;
  }
  .verification-brand-wall {
    max-width: 440px;
    width: 100%;
    gap: 9px;
    margin: 24px auto 8px;
    transform: rotate(-2deg);
    padding: 12px 5px;
  }
  .verification-brand-tile {
    min-height: 94px;
    border-radius: 17px;
  }
  .verification-brand-wall:before {
    inset: 0;
  }
  .verification-brand-wall .verification-logo img {
    width: 80px;
    height: 38px;
  }
  .verification-wall-caption {
    font-size: 8px;
  }
  .verification-section-heading {
    display: block;
  }
  .verification-section-heading h2,
  .verification-process h2 {
    font-size: 25px;
  }
  .verification-section-heading > span {
    display: block;
    margin-top: 12px;
  }
  .verification-tabs button {
    padding: 10px 13px;
    font-size: 12px;
  }
  .verification-search-row {
    flex-wrap: wrap;
  }
  .verification-search {
    flex-basis: 100%;
  }
  .verification-sort {
    width: 100%;
    justify-content: space-between;
  }
  .verification-sort select {
    max-width: none;
    flex: 1;
  }
  .verification-grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  .verification-card-art {
    padding-top: 48px;
  }
  .verification-card-body {
    padding: 22px;
  }
  .verification-process {
    margin-top: 40px;
  }
  .verification-process > div {
    grid-template-columns: 1fr;
    gap: 10px;
  }
  .verification-process p {
    padding: 19px;
  }
  .verification-conditions {
    padding: 22px;
    gap: 16px;
  }
  .verification-conditions > div {
    flex-basis: calc(100% - 50px);
  }
  .verification-conditions > a {
    margin-left: 40px;
  }
  .verification-detail {
    grid-template-columns: 1fr;
    padding: 20px;
    gap: 26px;
  }
  .verification-detail-art {
    min-height: 220px;
  }
  .verification-logo.large {
    height: 100px;
  }
  .verification-logo.large img {
    width: 200px;
    height: 75px;
  }
  .verification-detail-manual {
    margin-top: 22px;
  }
  .verification-detail-content h1 {
    font-size: 30px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .verification-card,
  .verification-card-cta {
    transition: none;
  }
  .verification-card:hover {
    transform: none;
  }
}
.verification-logo[data-brand="bybit"] img {
  background: #f1f3f8;
  border-radius: 10px;
  padding: 10px 12px;
}
.verification-brand-wall .verification-logo[data-brand="bybit"] img {
  padding: 9px;
}
.verification-logo.large[data-brand="bybit"] img {
  padding: 16px 20px;
  border-radius: 14px;
}

.verification-detail-price > span.flex {
  display: flex;
}
.verification-home-emblem {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}
.verification-home-emblem > div {
  display: flex;
  gap: 10px;
}
.verification-home-emblem img {
  object-fit: contain;
  width: 22px;
  height: 22px;
}

/* Private administration */
.admin-login {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 35px 20px;
  background: radial-gradient(ellipse at 50% 30%, #7961d51e, transparent 60%);
}
.admin-login-card {
  width: 100%;
  max-width: 480px;
  border: 1px solid #ffffff12;
  border-radius: 26px;
  background: linear-gradient(135deg, #ffffff05, #ffffff01);
  padding: 36px;
  box-shadow: 0 25px 100px #0003;
}
.admin-login-brand,
.admin-logo {
  display: flex;
  align-items: center;
  gap: 13px;
  font-weight: 650;
  letter-spacing: 0.04em;
  font-size: 14px;
}
.admin-login-brand > svg,
.admin-logo > svg {
  color: #b7a0ff;
}
.admin-login-brand small,
.admin-logo small {
  display: block;
  font-size: 8px;
  color: #707f98;
  letter-spacing: 0.23em;
  margin-top: 4px;
}
.admin-lock {
  display: inline-flex;
  padding: 15px;
  border: 1px solid #a78bfa33;
  background: #a78bfa12;
  color: #bba5ff;
  border-radius: 16px;
  margin: 38px 0 22px;
}
.admin-login-card h1 {
  font-size: 29px;
  font-weight: 650;
  letter-spacing: -0.025em;
  line-height: 1.2;
  margin: 15px 0;
}
.admin-login-card > p:not(.eyebrow) {
  font-size: 13px;
  color: #8c9ab3;
  line-height: 1.8;
}
.admin-login form {
  display: flex;
  flex-direction: column;
  gap: 18px;
  margin-top: 26px;
}
.admin-login label,
.admin-fields label {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: 12px;
  color: #95a3ba;
}
.admin-login input,
.admin-fields input,
.admin-fields select {
  background: #0b1020;
  border: 1px solid #ffffff16;
  border-radius: 12px;
  padding: 12px 14px;
  font-size: 14px;
  color: #e9e5fa;
  min-width: 0;
  outline: none;
}
.admin-login input:focus,
.admin-fields input:focus,
.admin-fields select:focus {
  border-color: #a78bfa88;
}
.admin-login .primary-button {
  justify-content: center;
  margin-top: 6px;
}
.admin-login-card > p.admin-login-note {
  font-size: 10px;
  color: #60728f;
  margin-top: 24px;
}
.admin-error {
  font-size: 12px;
  color: #fcbba8;
  line-height: 1.7;
}
.admin-shell {
  min-height: 100vh;
  display: grid;
  grid-template-columns: 252px minmax(0, 1fr);
}
.admin-sidebar {
  position: sticky;
  top: 0;
  height: 100vh;
  border-right: 1px solid #ffffff10;
  padding: 32px 20px;
  background: #090e18;
  display: flex;
  flex-direction: column;
}
.admin-logo {
  padding: 0 8px;
}
.admin-nav-caption {
  font-size: 9px;
  letter-spacing: 0.16em;
  color: #4f617e;
  margin: 46px 12px 16px;
}
.admin-sidebar nav {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.admin-sidebar nav button {
  display: flex;
  align-items: center;
  gap: 10px;
  text-align: left;
  padding: 13px 12px;
  color: #8596b0;
  border: 1px solid transparent;
  border-radius: 12px;
  font-size: 12px;
  cursor: pointer;
}
.admin-sidebar nav button.active {
  color: #d1c0ff;
  background: #a78bfa12;
  border-color: #a78bfa22;
}
.admin-sidebar nav button:hover {
  background: #ffffff04;
}
.admin-store-link {
  display: flex;
  gap: 12px;
  align-items: center;
  margin: 28px 12px;
  font-size: 12px;
  color: #8391ab;
}
.admin-user {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: auto;
  padding-top: 22px;
  border-top: 1px solid #ffffff10;
  min-width: 0;
}
.admin-user > div {
  min-width: 0;
  flex: 1;
}
.admin-user strong {
  font-size: 11px;
}
.admin-user p {
  font-size: 9px;
  color: #7e8da5;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin-top: 3px;
}
.admin-user-avatar {
  font-size: 12px;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 32px;
  height: 32px;
  border-radius: 10px;
  background: #a78bfa20;
  color: #c5afff;
}
.admin-user button {
  color: #8394b0;
  cursor: pointer;
}
.admin-main {
  padding: 44px 40px;
  max-width: 1700px;
  width: 100%;
  min-width: 0;
}
.admin-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
  margin-bottom: 30px;
}
.admin-header h1 {
  font-size: 34px;
  font-weight: 650;
  letter-spacing: -0.035em;
  margin: 12px 0;
}
.admin-header p:not(.eyebrow) {
  font-size: 13px;
  color: #8594af;
}
.admin-header .primary-button {
  font-size: 12px;
  white-space: nowrap;
}
.admin-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 15px;
  margin-bottom: 32px;
}
.admin-stats > div {
  background: linear-gradient(140deg, #ffffff05, #ffffff01);
  border: 1px solid #ffffff0e;
  border-radius: 18px;
  padding: 22px;
}
.admin-stats span {
  font-size: 11px;
  color: #7d8da8;
}
.admin-stats strong {
  display: block;
  font-size: 28px;
  margin-top: 12px;
  line-height: 1.2;
}
.admin-stats strong.admin-status {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 18px;
  color: #bda8ff;
  margin-top: 18px;
}
.admin-search {
  display: flex;
  align-items: center;
  gap: 10px;
  border: 1px solid #ffffff12;
  background: #ffffff02;
  padding: 0 15px;
  border-radius: 12px;
  margin-bottom: 20px;
  color: #788ba8;
}
.admin-search input {
  padding: 13px 0;
  background: none;
  outline: none;
  width: 100%;
  min-width: 0;
  color: #dde2ee;
  font-size: 13px;
}
.admin-table-wrap {
  border: 1px solid #ffffff10;
  border-radius: 18px;
  overflow: auto;
  background: #ffffff01;
}
.admin-table {
  width: 100%;
  text-align: left;
  border-collapse: collapse;
  white-space: nowrap;
}
.admin-table th {
  padding: 17px 20px;
  font-size: 10px;
  letter-spacing: 0.03em;
  color: #7e90ae;
  font-weight: 500;
  background: #ffffff02;
  border-bottom: 1px solid #ffffff0e;
}
.admin-table td {
  padding: 17px 20px;
  font-size: 12px;
  border-bottom: 1px solid #ffffff0b;
  color: #a8b6ce;
}
.admin-table tbody tr:last-child td {
  border-bottom: 0;
}
.admin-table tbody tr:hover {
  background: #ffffff02;
}
.admin-product-name {
  display: flex;
  align-items: center;
  gap: 13px;
}
.admin-product-name > div {
  width: 42px;
  height: 42px;
  background: #ffffff07;
  border: 1px solid #ffffff0c;
  border-radius: 11px;
  padding: 7px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #a891df;
}
.admin-product-name img {
  width: 28px;
  height: 28px;
  object-fit: contain;
}
.admin-product-name strong {
  font-size: 12px;
  font-weight: 550;
  color: #e0e5f0;
  display: block;
}
.admin-product-name small {
  display: block;
  margin-top: 5px;
  font-size: 9px;
  color: #6c7f9b;
}
.admin-price {
  font-weight: 600;
  color: #e6eaf5 !important;
}
.admin-price small {
  font-size: 9px;
  color: #7b8eaa;
  font-weight: 400;
}
.admin-pill {
  font-size: 9px;
  border: 1px solid #ffffff10;
  background: #ffffff04;
  color: #8e9db5;
  border-radius: 20px;
  padding: 5px 9px;
}
.admin-pill.published {
  color: #73dbba;
  background: #73dbba0c;
  border-color: #73dbba1a;
}
.admin-edit {
  display: flex;
  align-items: center;
  gap: 7px;
  border: 1px solid #a78bfa2c;
  background: #a78bfa0b;
  color: #bdabed;
  font-size: 10px;
  border-radius: 10px;
  padding: 9px 12px;
  cursor: pointer;
}
.admin-message {
  margin-bottom: 22px;
  border: 1px solid #a78bfa33;
  background: #a78bfa0a;
  color: #c8b6fa;
  font-size: 12px;
  padding: 14px 18px;
  border-radius: 12px;
}
.admin-library-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 14px;
}
.admin-library-grid article {
  border: 1px solid #ffffff10;
  background: #ffffff03;
  border-radius: 18px;
  padding: 20px 13px;
  text-align: center;
}
.admin-library-grid img {
  width: 65px;
  height: 60px;
  object-fit: contain;
  margin: 3px auto 17px;
}
.admin-library-grid h2 {
  font-size: 12px;
  font-weight: 550;
  min-height: 32px;
  line-height: 1.4;
}
.admin-library-grid button {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: 12px;
  font-size: 9px;
  color: #bba8f2;
  cursor: pointer;
}
.admin-editor {
  border: 1px solid #ffffff10;
  background: #ffffff02;
  border-radius: 22px;
  padding: 26px;
}
.admin-editor-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 26px;
}
.admin-editor-top h2 {
  font-size: 22px;
  font-weight: 600;
}
.admin-editor-top button {
  font-size: 12px;
  color: #9cacc5;
  cursor: pointer;
}
.admin-editor-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 35px;
}
.admin-fields {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}
.admin-price-inputs {
  display: grid;
  grid-template-columns: 1fr 120px;
  gap: 12px;
}
.admin-field-note {
  font-size: 10px;
  color: #70839f;
  line-height: 1.8;
}
.admin-fields label.admin-check {
  flex-direction: row;
  align-items: center;
  gap: 9px;
  margin-top: 4px;
}
.admin-check input {
  width: 16px;
  height: 16px;
  accent-color: #a78bfa;
}
.admin-selected-logo {
  min-height: 150px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border: 1px solid #ffffff0f;
  background: radial-gradient(ellipse, #a78bfa0e, transparent 80%);
  border-radius: 16px;
  margin-bottom: 18px;
}
.admin-selected-logo > img {
  width: 160px;
  height: 65px;
  object-fit: contain;
}
.admin-selected-logo > svg {
  color: #a78bfa;
}
.admin-selected-logo strong {
  font-size: 12px;
}
.admin-selected-logo button {
  font-size: 9px;
  color: #7789a3;
  cursor: pointer;
}
.admin-picker-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 9px;
  max-height: 410px;
  overflow: auto;
  padding: 2px;
}
.admin-picker-grid button {
  border: 1px solid #ffffff10;
  border-radius: 12px;
  padding: 12px 8px;
  text-align: center;
  cursor: pointer;
}
.admin-picker-grid button.selected {
  background: #a78bfa14;
  border-color: #a78bfa77;
}
.admin-picker-grid img {
  width: 70px;
  height: 35px;
  object-fit: contain;
  margin: 0 auto 9px;
}
.admin-picker-grid span {
  font-size: 9px;
  line-height: 1.5;
  display: block;
  color: #a9b4c6;
}
.admin-login button:disabled,
.admin-editor button:disabled {
  opacity: 0.5;
}
.admin-shell button:focus-visible,
.admin-login button:focus-visible {
  outline: 2px solid #a78bfa;
  outline-offset: 3px;
}
@media (max-width: 1150px) {
  .admin-shell {
    grid-template-columns: 220px minmax(0, 1fr);
  }
  .admin-main {
    padding: 35px 24px;
  }
  .admin-library-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .admin-editor-grid {
    gap: 22px;
  }
}
@media (max-width: 760px) {
  .admin-shell {
    grid-template-columns: 1fr;
  }
  .admin-sidebar {
    height: auto;
    position: static;
    padding: 20px;
    border-right: 0;
    border-bottom: 1px solid #ffffff10;
  }
  .admin-nav-caption,
  .admin-store-link {
    display: none;
  }
  .admin-sidebar nav {
    flex-direction: row;
    margin-top: 20px;
    overflow: auto;
  }
  .admin-sidebar nav button {
    font-size: 10px;
    white-space: nowrap;
    padding: 10px;
  }
  .admin-user {
    padding-top: 14px;
    margin-top: 16px;
  }
  .admin-main {
    padding: 28px 18px;
  }
  .admin-header {
    align-items: start;
    flex-direction: column;
    gap: 18px;
  }
  .admin-header h1 {
    font-size: 30px;
  }
  .admin-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
  }
  .admin-stats > div {
    padding: 17px;
  }
  .admin-editor {
    padding: 20px 15px;
  }
  .admin-editor-grid {
    grid-template-columns: 1fr;
  }
  .admin-library-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .admin-login-card {
    padding: 28px;
  }
  .admin-editor-top h2 {
    font-size: 19px;
  }
  .admin-logo {
    font-size: 12px;
  }
}
.admin-shell img[src$="/bybit.png"] {
  background: #f1f3f8;
  padding: 4px;
  border-radius: 5px;
}
.admin-sidebar {
  min-width: 0;
}
.admin-sidebar nav {
  min-width: 0;
  max-width: 100%;
}
@media (max-width: 760px) {
  .admin-shell {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* Supplier catalog: finite pages keep a large API catalog responsive on mobile. */
.smm-browser {
  margin-top: 28px;
}
.smm-catalog-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  margin-bottom: 22px;
}
.smm-catalog-heading h2,
.smm-selected-detail h2 {
  font-size: 27px;
  font-weight: 650;
  letter-spacing: -0.8px;
}
.smm-status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #79dcbc;
  display: inline-block;
  margin-right: 7px;
}
.smm-browse-platforms {
  overflow: auto;
  flex-wrap: nowrap;
  padding-bottom: 12px;
  scrollbar-width: thin;
}
.smm-browse-platforms button {
  white-space: nowrap;
  flex-shrink: 0;
}
.smm-platform-mark {
  display: inline-grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 8px;
  background: #2d294b;
  color: #d0b5ff;
  font-size: 10px;
  font-weight: 800;
  flex-shrink: 0;
}
.mark-youtube {
  background: #482334;
  color: #ff9191;
}
.mark-facebook {
  background: #20355b;
  color: #89baff;
}
.mark-spotify {
  background: #173e35;
  color: #8bf2ae;
}
.mark-twitter {
  background: #303340;
  color: white;
}
.smm-search-controls {
  display: grid;
  grid-template-columns: 1.2fr 1fr 0.65fr;
  gap: 12px;
  margin: 18px 0;
}
.smm-search-controls label {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  background: #131624;
  border: 1px solid #2b2b40;
  border-radius: 12px;
  padding: 0 14px;
  color: #9194b0;
}
.smm-search-controls input,
.smm-search-controls select {
  min-width: 0;
  width: 100%;
  height: 48px;
  background: transparent;
  color: #e4e4f0;
  outline: none;
  font-size: 13px;
}
.smm-search-controls select option {
  background: #171b2a;
}
.smm-search-controls label:focus-within {
  border-color: #8873d3;
}
.smm-catalog-meta {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin: 20px 0;
  color: #989db4;
  font-size: 12px;
}
.smm-catalog-meta > div {
  display: flex;
  gap: 20px;
}
.smm-catalog-meta label {
  display: flex;
  align-items: center;
  gap: 8px;
}
.smm-catalog-meta input {
  accent-color: #9b79f8;
  width: 14px;
  height: 14px;
}
.smm-service-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}
.smm-service-card {
  display: flex;
  flex-direction: column;
  min-width: 0;
  border: 1px solid #2a293d;
  background: linear-gradient(150deg, #191b2bba, #111521e8);
  backdrop-filter: blur(14px);
  border-radius: 18px;
  padding: 20px;
  transition:
    border-color 0.2s,
    transform 0.2s;
}
.smm-service-card:hover {
  border-color: #66528b;
  transform: translateY(-2px);
}
.smm-service-card.is-selected {
  border-color: #a08ada;
}
.smm-card-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  font-size: 12px;
}
.smm-card-top > span:first-child {
  display: flex;
  gap: 8px;
  align-items: center;
  font-weight: 600;
}
.smm-service-id {
  color: #8c8fa8;
  font-size: 11px;
  font-family: monospace;
}
.smm-card-category {
  font-size: 11px;
  color: #8e83b7;
  margin: 16px 0 8px;
  line-height: 1.5;
}
.smm-service-card h3 {
  font-size: 14px;
  font-weight: 550;
  line-height: 1.65;
  margin-bottom: 16px;
  overflow-wrap: anywhere;
}
.smm-card-badges {
  display: flex;
  gap: 6px;
  margin-top: auto;
  flex-wrap: wrap;
  min-height: 24px;
  margin-bottom: 16px;
}
.smm-card-badges > span {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 3px 7px;
  border-radius: 6px;
  color: #8fd6bc;
  background: #14382f80;
  font-size: 10px;
}
.smm-card-badges > span.special-type {
  color: #d6b48e;
  background: #3d2c2180;
}
.smm-card-price {
  display: flex;
  justify-content: space-between;
  align-items: start;
  border-top: 1px solid #2a293b;
  padding-top: 16px;
  gap: 6px;
}
.smm-card-price > span:last-child {
  color: #7d819a;
  font-size: 11px;
  padding-top: 5px;
  max-width: 100px;
  text-align: right;
}
.smm-card-range {
  font-size: 11px;
  color: #8a8fa9;
  margin: 14px 0;
}
.smm-service-card > button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #28213c;
  border: 1px solid #463460;
  color: #ddd1f9;
  border-radius: 10px;
  padding: 11px 12px;
  font-size: 12px;
  transition: background 0.2s;
}
.smm-service-card > button:hover {
  background: #3e2e5c;
}
.smm-pagination {
  display: flex;
  gap: 20px;
  align-items: center;
  justify-content: center;
  margin: 26px 0;
  font-size: 13px;
  color: #aba7c2;
}
.smm-pagination button {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border: 1px solid #363149;
  border-radius: 9px;
  background: #1a192b;
}
.smm-pagination button:disabled {
  opacity: 0.35;
}
.smm-source-note {
  display: flex;
  gap: 10px;
  align-items: start;
  color: #868da5;
  font-size: 12px;
  line-height: 1.8;
  padding: 16px;
  border: 1px solid #242a3e;
  border-radius: 12px;
}
.smm-source-note svg {
  flex-shrink: 0;
  margin-top: 3px;
}
.smm-selected-detail {
  margin-top: 38px;
  scroll-margin-top: 90px;
}
.smm-selected-detail h2 {
  margin: 8px 0 20px;
}
.smm-selected-detail .smm-platforms[hidden] {
  display: none;
}
.smm-skeleton {
  height: 290px;
  gap: 25px;
}
.smm-skeleton div {
  height: 20px;
  border-radius: 7px;
  background: #282a40;
}
.smm-skeleton div:nth-child(2) {
  height: 90px;
}
.smm-empty {
  padding: 35px;
  border: 1px dashed #36334a;
  border-radius: 14px;
  color: #c0b8d0;
  text-align: center;
}
.smm-empty button {
  display: flex;
  margin: 15px auto 0;
  gap: 7px;
  align-items: center;
}
.smm-summary h3 {
  overflow-wrap: anywhere;
}
.smm-form select {
  max-width: 100%;
}
@media (max-width: 1000px) {
  .smm-service-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .smm-search-controls {
    grid-template-columns: 1fr 1fr;
  }
  .smm-search-controls .smm-search {
    grid-column: 1/-1;
  }
}
@media (max-width: 600px) {
  .smm-service-grid {
    grid-template-columns: 1fr;
  }
  .smm-catalog-heading {
    align-items: start;
    flex-direction: column;
  }
  .smm-catalog-heading h2 {
    font-size: 24px;
  }
  .smm-catalog-meta {
    flex-direction: column;
  }
  .smm-catalog-meta > div {
    gap: 14px;
  }
  .smm-search-controls {
    gap: 8px;
  }
  .smm-search-controls label {
    padding: 0 10px;
  }
  .smm-search-controls select {
    font-size: 11px;
  }
  .smm-service-card {
    padding: 18px;
  }
  .smm-card-badges {
    margin-top: 0;
  }
  .smm-selected-detail h2 {
    font-size: 23px;
  }
}

/* Unified commerce and guided tour */
.shop-panel {
  border: 1px solid #303044;
  border-radius: 20px;
  padding: 25px;
  background: linear-gradient(135deg, #181c2bd9, #111622ed);
  backdrop-filter: blur(14px);
}
.shop-title {
  font-size: clamp(28px, 4vw, 44px);
  font-weight: 650;
  letter-spacing: -1.4px;
  margin: 8px 0 25px;
}
.shop-title > span {
  font-size: 18px;
  color: #a99dc3;
  margin-left: 10px;
}
.shop-panel h1 {
  font-size: 30px;
  font-weight: 650;
  margin: 12px 0 25px;
}
.shop-panel h2 {
  font-size: 20px;
  font-weight: 600;
  margin-bottom: 16px;
}
.shop-panel label {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: 13px;
  color: #a8adc3;
  margin: 16px 0;
}
.shop-panel input:not([type="checkbox"]),
.shop-panel select,
.shop-panel textarea {
  width: 100%;
  min-width: 0;
  background: #0d1220;
  border: 1px solid #32344c;
  border-radius: 10px;
  padding: 12px;
  color: #ececf6;
  font-size: 14px;
}
.shop-panel textarea {
  resize: vertical;
}
.shop-panel input:focus,
.shop-panel textarea:focus {
  border-color: #9b78e9;
}
.shop-panel select option {
  background: #101522;
}
.shop-muted {
  font-size: 13px;
  color: #959eb6;
  line-height: 1.8;
}
.shop-error {
  color: #e8b18e;
  font-size: 13px;
  line-height: 1.7;
  margin: 15px 0;
}
.shop-panel button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.shop-text-button {
  font-size: 13px;
  color: #b8a0e8;
  margin-top: 20px;
}
.shop-login {
  max-width: 480px;
  margin: 25px auto 70px;
}
.shop-login form .primary-button {
  width: 100%;
  margin-top: 23px;
}
.shop-telegram-widget {
  margin-top: 26px;
  min-height: 8px;
}
.shop-buy-button {
  margin-top: 18px;
}
.shop-cart-link {
  display: flex;
  gap: 5px;
  align-items: center;
}
.shop-cart-link span {
  font-size: 10px;
  border-radius: 20px;
  background: #554076;
  padding: 2px 5px;
}
.shop-checkout-layout {
  display: grid;
  grid-template-columns: 1fr 350px;
  gap: 25px;
  align-items: start;
}
.shop-cart-list {
  display: grid;
  gap: 14px;
}
.shop-cart-row {
  display: flex;
  justify-content: space-between;
  gap: 22px;
}
.shop-cart-row h2 {
  font-size: 16px;
  line-height: 1.7;
  margin-top: 12px;
  overflow-wrap: anywhere;
}
.shop-cart-row > div:last-child {
  display: flex;
  flex-direction: column;
  gap: 22px;
  align-items: end;
  flex-shrink: 0;
}
.shop-cart-row button {
  color: #a8a4b9;
}
.shop-target-url {
  font-size: 12px;
  overflow-wrap: anywhere;
  color: #9c8ec0;
}
.shop-checkout-summary {
  position: sticky;
  top: 25px;
}
.shop-checkout-summary > svg {
  color: #a689e8;
  margin-bottom: 20px;
}
.shop-checkout-summary .primary-button {
  width: 100%;
}
.shop-panel .shop-terms {
  flex-direction: row;
  align-items: start;
  line-height: 1.8;
  margin: 22px 0;
}
.shop-terms input {
  margin-top: 4px;
  accent-color: #9f7bf1;
  flex-shrink: 0;
}
.shop-invoice {
  display: grid;
  gap: 12px;
  margin-top: 22px;
  font-size: 12px;
  color: #b59cdd;
}
.shop-empty {
  padding: 60px;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 22px;
}
.shop-account-heading {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: center;
  margin-bottom: 30px;
}
.shop-account-heading .shop-title {
  margin-bottom: 6px;
}
.shop-account-heading > button {
  font-size: 13px;
  color: #aaa4bd;
}
.shop-wallet-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-bottom: 24px;
}
.shop-wallet {
  position: relative;
  overflow: hidden;
}
.shop-wallet::after {
  content: "";
  position: absolute;
  width: 150px;
  height: 150px;
  border-radius: 50%;
  background: #9b61ff14;
  filter: blur(30px);
  right: -10px;
  top: -10px;
}
.shop-wallet > svg {
  color: #b295ed;
}
.shop-wallet p {
  color: #949ab2;
  font-size: 12px;
  margin: 20px 0 8px;
}
.shop-wallet strong {
  font-size: 36px;
  font-weight: 600;
  letter-spacing: -1px;
}
.shop-wallet strong span {
  font-size: 16px;
  color: #a994d0;
  letter-spacing: 0;
  margin-left: 12px;
}
.shop-deposit-form {
  display: grid;
  grid-template-columns: 1fr 1.4fr auto;
  gap: 20px;
  align-items: end;
}
.shop-deposit-form .primary-button {
  margin-bottom: 16px;
  height: 45px;
}
.shop-order-section {
  margin: 38px 0;
}
.shop-section-title,
.shop-section-title h2 {
  display: flex;
  align-items: center;
  gap: 10px;
}
.shop-section-title {
  justify-content: space-between;
  margin-bottom: 18px;
}
.shop-section-title h2 {
  font-size: 24px;
}
.shop-order {
  margin-bottom: 14px;
}
.shop-order-heading {
  display: flex;
  flex-wrap: wrap;
  gap: 15px;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: #a3a7bd;
  padding-bottom: 16px;
  border-bottom: 1px solid #303045;
}
.shop-order-heading strong {
  color: #f2edff;
}
.shop-status {
  font-size: 10px;
  color: #b9a4e7;
  background: #68518d26;
  padding: 5px 9px;
  border-radius: 6px;
}
.shop-order-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 18px;
  padding: 18px 0;
}
.shop-order-item h3 {
  font-size: 14px;
  line-height: 1.7;
  overflow-wrap: anywhere;
}
.shop-order-item .secondary-button {
  font-size: 12px;
  flex-shrink: 0;
}
.shop-payment-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 15px;
  padding: 14px 0;
  border-bottom: 1px solid #292c3d;
  font-size: 12px;
  overflow-wrap: anywhere;
}
.shop-payment-row button {
  display: flex;
  gap: 6px;
  align-items: center;
  color: #b79cdc;
}
.shop-panel.shop-order-item {
  padding: 20px;
}
.steam-game-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 10px;
  margin: 25px 0;
}
.steam-game-grid a {
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: center;
  justify-content: center;
  border: 1px solid #2a3045;
  border-radius: 13px;
  padding: 13px;
  font-size: 11px;
  text-align: center;
  background: #171a28;
}
.steam-game-grid a.selected {
  border-color: #a186d5;
  background: #3c2b594d;
}
.steam-game-grid img {
  height: 65px;
  max-width: 100%;
  object-fit: contain;
  border-radius: 7px;
}
.steam-search {
  display: flex;
  gap: 14px;
  margin-bottom: 25px;
}
.steam-search > input {
  flex: 1;
}
.steam-search select {
  width: 230px;
}
.steam-listing-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 17px;
}
.steam-listing {
  display: flex;
  flex-direction: column;
  align-items: start;
  min-width: 0;
}
.steam-listing > img {
  height: 150px;
  width: 100%;
  object-fit: contain;
  margin-bottom: 20px;
}
.steam-listing small {
  color: #9d8cb9;
  font-size: 10px;
}
.steam-listing h2 {
  font-size: 15px;
  line-height: 1.7;
  overflow-wrap: anywhere;
  margin: 10px 0 20px;
  flex: 1;
}
.steam-listing .shop-buy-button {
  width: 100%;
  margin-top: 18px;
}
.commerce-admin {
  max-width: 1400px;
  margin: auto;
  padding: 40px 25px 80px;
}
.admin-metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 15px;
  margin: 25px 0;
}
.admin-metrics p {
  color: #9da1b7;
  font-size: 12px;
  margin: 15px 0 8px;
}
.admin-metrics strong {
  font-size: 22px;
  font-weight: 600;
}
.admin-order-filters {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}
.admin-order-filters label {
  margin: 0;
  min-width: 230px;
}
.shop-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 200;
  background: #03050ddb;
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}
.shop-modal {
  width: min(620px, 100%);
  max-height: 90svh;
  overflow: auto;
}
.shop-modal-close {
  display: block;
  margin-left: auto;
  font-size: 12px;
  color: #9f9eb5;
  margin-bottom: 14px;
}
.shop-modal p {
  font-size: 13px;
  line-height: 1.8;
  color: #a0a6be;
}
.shop-modal .primary-button {
  width: 100%;
  margin-top: 18px;
}
.tour-page {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  gap: 65px;
  min-height: 650px;
}
.tour-intro {
  padding: 24px 0;
}
.tour-intro h1 {
  font-size: clamp(34px, 4vw, 54px);
  line-height: 1.15;
  letter-spacing: -2px;
  font-weight: 650;
  margin: 22px 0;
}
.tour-intro h1 span {
  display: block;
  color: #a29baa;
  margin-top: 10px;
}
.tour-intro > p:not(.eyebrow) {
  font-size: 14px;
  line-height: 1.8;
  color: #989fb5;
  max-width: 320px;
}
.tour-intro nav {
  display: grid;
  gap: 10px;
  margin: 33px 0;
}
.tour-intro nav button {
  display: flex;
  align-items: center;
  gap: 16px;
  text-align: left;
  padding: 15px;
  border: 1px solid transparent;
  border-radius: 13px;
  color: #828ba3;
  transition: 0.2s;
}
.tour-intro nav button[aria-current] {
  border-color: #79619266;
  background: #5c407725;
  color: #e8dbff;
}
.tour-intro nav button > span {
  font-size: 13px;
  background: #23273b;
  padding: 10px;
  border-radius: 9px;
}
.tour-intro nav strong {
  display: block;
  font-size: 14px;
  font-weight: 550;
}
.tour-intro nav small {
  display: block;
  font-size: 11px;
  margin-top: 4px;
  color: #838ba4;
}
.tour-mode-label {
  font-size: 10px;
  letter-spacing: 2px;
  color: #88879e;
  padding: 0 15px;
}
.tour-mode-label span {
  color: #b389f3;
  padding: 0 12px;
}
.tour-stage {
  border: 1px solid #373247;
  border-radius: 28px;
  background:
    radial-gradient(ellipse at 80% 10%, #74489c28, transparent 65%),
    linear-gradient(120deg, #171c2e, #111625);
  padding: 30px;
  display: flex;
  flex-direction: column;
  box-shadow: 0 20px 70px #0002;
}
.tour-progress {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  color: #918aa5;
  margin-bottom: 35px;
}
.tour-progress > div {
  display: flex;
  gap: 6px;
}
.tour-progress > div span {
  width: 28px;
  height: 3px;
  background: #313044;
  border-radius: 5px;
}
.tour-progress > div span.active {
  background: #bb99ed;
  box-shadow: 0 0 10px #a477cf44;
}
.tour-slide {
  flex: 1;
}
.tour-slide h2 {
  font-size: clamp(27px, 3vw, 39px);
  letter-spacing: -1.5px;
  line-height: 1.25;
  font-weight: 650;
  margin: 16px 0;
}
.tour-slide h2 span {
  display: block;
  color: #bf9bed;
}
.tour-slide > p:not(.eyebrow) {
  color: #a0a8bc;
  font-size: 13px;
  line-height: 1.9;
  max-width: 490px;
}
.tour-categories {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin: 30px 0;
}
.tour-categories a {
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 19px 15px;
  border: 1px solid #343248;
  border-radius: 14px;
  background: #1117278c;
  transition:
    transform 0.2s,
    border 0.2s;
}
.tour-categories a:hover {
  transform: translateY(-3px);
