}
.tour-finish-art > div {
  border: 1px solid #ae81ee66;
  border-radius: 30px;
  background: radial-gradient(circle, #8b61c85c, #2e274a);
  padding: 25px;
  color: #d4b8ff;
  box-shadow: 0 0 80px #b074d724;
}
.tour-finish-art > span {
  font-size: 11px;
  letter-spacing: 4px;
  margin-top: 25px;
  color: #c2a6e6;
}
.tour-finish-art > p {
  color: #9995ac;
  font-size: 11px;
  margin-top: 13px;
}
.tour-shop-link {
  font-size: 12px;
  color: #ae99ca;
  text-align: right;
  margin-top: 20px;
}
@media (max-width: 1000px) {
