/* Animated Telegram NFT Gift Emojis */
@keyframes emojiFloat {
  0%,
  100% {
    transform: translateY(0px) rotate(0deg) scale(1);
  }
  50% {
    transform: translateY(-5px) rotate(1.5deg) scale(1.03);
  }
}

@keyframes emojiGlow {
  0%,
  100% {
    opacity: 0.35;
    transform: scale(0.95);
  }
  50% {
    opacity: 0.75;
    transform: scale(1.1);
  }
}

.animate-emoji-float {
  animation: emojiFloat 3.4s ease-in-out infinite;
}

.animate-emoji-glow {
  animation: emojiGlow 2.8s ease-in-out infinite;
}
/* Telegram viewport, native theme and gesture-safe spacing. */
:root {
  --app-bg: var(--tg-theme-bg-color, #0b0f19);
  --app-text: var(--tg-theme-text-color, #f5f5fa);
  --app-panel: var(--tg-theme-secondary-bg-color, #101624);
  --app-muted: var(--tg-theme-hint-color, #a5b1c4);
  --app-button: var(--tg-theme-button-color, #9274f9);
  --app-bottom-safe: max(
    var(--tg-safe-area-inset-bottom, 0px),
    var(--tg-content-safe-area-inset-bottom, 0px),
    env(safe-area-inset-bottom, 0px)
  );
}
html,
body {
  overscroll-behavior-y: contain;
  touch-action: pan-y;
}
body {
  background-color: var(--app-bg);
  color: var(--app-text);
}
[data-telegram="true"] {
  --surface: var(--app-panel);
  --muted: var(--app-muted);
  --accent: var(--app-button);
}
[data-theme="light"] body {
  background-image: none;
}
.miniapp,
.web-shell,
.standalone-module {
  min-height: var(--tg-viewport-height, 100svh);
  padding-top: max(
    var(--tg-safe-area-inset-top, 0px),
    var(--tg-content-safe-area-inset-top, 0px),
    env(safe-area-inset-top, 0px)
  );
  padding-bottom: max(var(--tg-safe-area-inset-bottom, 0px), 80px);
  padding-left: max(
    var(--tg-safe-area-inset-left, 0px),
    var(--tg-content-safe-area-inset-left, 0px)
  );
  padding-right: max(
    var(--tg-safe-area-inset-right, 0px),
    var(--tg-content-safe-area-inset-right, 0px)
  );
}
.app-bottom-nav {
  position: fixed;
  inset: auto 0 0;
  padding-bottom: calc(10px + var(--app-bottom-safe));
  background: var(--app-panel);
  color: var(--app-text);
}
.miniapp main,
.web-shell main {
  padding-bottom: calc(24px + var(--app-bottom-safe));
}
.wallet-connect,
.wallet-connect-placeholder {
  width: 160px;
  height: 40px;
  flex-shrink: 0;
}
.nft-catalog {
  color: var(--app-text);
  max-width: 1080px;
  margin: 0 auto;
}
.nft-catalog-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
}
.nft-catalog-header h1 {
  font-size: clamp(26px, 5vw, 42px);
  line-height: 1.12;
  font-weight: 800;
  margin: 12px 0;
  letter-spacing: -0.04em;
}
.nft-catalog-header p,
.gift-muted {
  color: var(--app-muted);
}
.nft-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  letter-spacing: 0.12em;
  color: var(--app-button);
  font-weight: 700;
}
.gift-cart,
.nft-controls button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px;
  border: 1px solid color-mix(in srgb, var(--app-text) 15%, transparent);
  border-radius: 14px;
  background: var(--app-panel);
}
.nft-market-status {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 12px;
  color: var(--app-muted);
  margin-bottom: 14px;
}
.status-live {
  color: #16a978;
}
.status-demo {
  color: var(--app-button);
}
.nft-notice {
  padding: 12px 16px;
  border-radius: 12px;
  background: var(--app-panel);
  color: var(--app-muted);
  font-size: 13px;
  margin: 12px 0;
}
.nft-controls {
  display: flex;
  gap: 12px;
  margin: 24px 0 16px;
}
.gift-search {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 10px;
  background: var(--app-panel);
  padding: 12px 16px;
  border-radius: 14px;
  min-width: 0;
}
.gift-search input {
  background: transparent;
  width: 100%;
  min-width: 0;
  outline: none;
}
.nft-filters {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}
.nft-filters label {
  color: var(--app-muted);
  font-size: 12px;
}
.nft-filters input,
.nft-filters select {
  display: block;
  color: var(--app-text);
  width: 100%;
  min-height: 44px;
  background: var(--app-panel);
  border: 1px solid color-mix(in srgb, var(--app-text) 12%, transparent);
  border-radius: 10px;
  padding: 10px;
  margin-top: 5px;
}
.nft-filters [aria-invalid="true"] {
  border-color: #d45656;
}
.nft-results-bar {
  display: flex;
  justify-content: space-between;
  color: var(--app-muted);
  font-size: 12px;
  margin: 20px 0;
}
.nft-results-bar button {
  color: var(--app-button);
  min-height: 32px;
}
.nft-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
}
.nft-gift-card {
  position: relative;
  overflow: hidden;
  border-radius: 22px;
  background: var(--app-panel);
  border: 1px solid color-mix(in srgb, var(--app-text) 10%, transparent);
}
.gift-preview {
  display: block;
  width: 100%;
  aspect-ratio: 1;
  padding: 10px;
  position: relative;
}
.gift-preview img,
.gift-modal-preview img {
  aspect-ratio: 1;
  object-fit: contain;
}
.gift-number,
.gift-rarity {
  position: absolute;
  bottom: 20px;
  font-size: 11px;
  font-weight: 700;
  color: white;
  background: #12141ca6;
  padding: 5px 9px;
  border-radius: 20px;
}
.gift-number {
  left: 20px;
}
.gift-rarity {
  right: 20px;
}
.gift-favorite {
  position: absolute;
  top: 20px;
  right: 20px;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: white;
  background: #12141c80;
}
.gift-favorite[aria-pressed="true"] {
  color: #ff93b6;
}
.gift-card-details {
  padding: 6px 16px 16px;
}
.gift-name {
  text-align: left;
  font-size: 16px;
  font-weight: 750;
  min-height: 44px;
}
.gift-card-details p {
  color: var(--app-muted);
  font-size: 12px;
  min-height: 32px;
}
.gift-prices {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin: 12px 0;
}
.gift-prices strong {
  font-size: 20px;
}
.gift-prices span {
  font-size: 11px;
  color: var(--app-muted);
}
.gift-add {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 8px;
  min-height: 44px;
  padding: 10px;
  width: 100%;
  border-radius: 12px;
  background: var(--app-button);
  color: var(--tg-theme-button-text-color, #fff);
  font-size: 13px;
  font-weight: 700;
}
.gift-add:disabled {
  background: color-mix(in srgb, var(--app-text) 8%, var(--app-panel));
  color: var(--app-muted);
  cursor: default;
}
.nft-controls button[aria-pressed="true"] {
  color: var(--app-button);
  border-color: var(--app-button);
}
.nft-dialog {
  padding: 0;
  background: var(--app-panel);
  color: var(--app-text);
  border: 1px solid color-mix(in srgb, var(--app-text) 15%, transparent);
  border-radius: 24px;
  width: min(840px, calc(100vw - 24px));
  max-height: calc(
    var(--tg-viewport-height, 100svh) -
      max(
        var(--tg-safe-area-inset-top, 0px),
        var(--tg-content-safe-area-inset-top, 0px)
      ) -
      var(--app-bottom-safe) - 24px
  );
  margin: auto;
  overscroll-behavior-y: contain;
}
.nft-dialog::backdrop {
  background: #030713c7;
  backdrop-filter: blur(8px);
}
.nft-dialog-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  padding: 24px;
  gap: 24px;
  position: relative;
}
.gift-close {
  position: absolute;
  right: 12px;
  top: 12px;
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  background: var(--app-panel);
  border-radius: 50%;
  z-index: 2;
}
.gift-modal-preview {
  width: 100%;
  aspect-ratio: 1;
  align-self: start;
}
.gift-modal-details {
  padding-top: 22px;
}
.gift-modal-details h2 {
  font-size: 25px;
  font-weight: 800;
  margin: 12px 0;
}
.gift-attributes {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin: 20px 0;
}
.gift-attributes div {
  background: color-mix(in srgb, var(--app-text) 5%, transparent);
  padding: 10px 12px;
  border-radius: 12px;
}
.gift-attributes dt {
  color: var(--app-muted);
  font-size: 11px;
}
.gift-attributes dd {
  font-size: 14px;
  margin-top: 4px;
  overflow-wrap: anywhere;
}
.gift-checkout-link {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  color: var(--app-button);
  margin-top: 10px;
}
.nft-empty {
  text-align: center;
  padding: 50px 0;
  color: var(--app-muted);
}
.nft-toast {
  position: fixed;
  left: 50%;
  bottom: calc(100px + var(--app-bottom-safe));
  transform: translateX(-50%);
  padding: 14px 24px;
  background: var(--app-panel);
  border: 1px solid var(--app-button);
  border-radius: 14px;
  z-index: 80;
}
.nft-skeleton {
  aspect-ratio: 0.7;
  border-radius: 22px;
  background: var(--app-panel);
}
@media (max-width: 640px) {
  .nft-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
  }
  .nft-filters {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .nft-dialog-content {
    grid-template-columns: 1fr;
    padding: 18px;
    gap: 0;
  }
  .gift-modal-preview {
    max-width: 300px;
    margin: auto;
  }
  .gift-prices strong {
    font-size: 17px;
  }
  .gift-card-details {
    padding: 0 10px 12px;
  }
  .gift-name {
    font-size: 13px;
  }
  .nft-controls {
    flex-wrap: wrap;
  }
  .gift-search {
    flex-basis: 100%;
  }
  .gift-add {
    font-size: 11px;
  }
}
[data-theme="light"] .shop-panel {
  background: var(--app-panel);
  color: var(--app-text);
}

/* Electric Blue — shared product system. */
:root {
  --brand-blue: #2a85ff;
  --app-bg: var(--tg-theme-bg-color, #0b0e14);
  --app-panel: var(--tg-theme-secondary-bg-color, #111622);
  --app-button: #2a85ff;
  --accent: #2a85ff;
  --tg-safe-bottom: max(
    16px,
    var(--tg-safe-area-inset-bottom, 0px),
    var(--tg-content-safe-area-inset-bottom, 0px),
    env(safe-area-inset-bottom, 0px)
  );
}
body {
  background-color: var(--app-bg);
  background-image: radial-gradient(
    ellipse at top,
    rgba(42, 133, 255, 0.18),
    transparent 65%
  );
}
button,
a {
