}
.nft-gift-card {
  border-color: color-mix(in srgb, var(--rarity-glow) 22%, transparent);
  box-shadow: 0 4px 24px color-mix(in srgb, var(--rarity-glow) 9%, transparent);
  border-radius: 24px;
