}
.nft-results-bar {
  margin: 12px 0;
  font-size: 10px;
}
.app-bottom-nav {
  padding: 9px 8px calc(9px + var(--tg-safe-bottom));
  border-top: 1px solid #2a85ff20;
  background: color-mix(in srgb, var(--app-bg) 90%, transparent);
  backdrop-filter: blur(20px);
}
.app-bottom-nav a {
  position: relative;
  isolation: isolate;
  padding: 10px 3px;
  border-radius: 18px;
  color: var(--app-muted);
  font-size: 8px;
}
.app-bottom-nav a > *:not(.nav-active-pill) {
  position: relative;
  z-index: 1;
}
.app-bottom-nav .active {
  color: #2a85ff;
}
.nav-active-pill {
  position: absolute;
