  border: 1px solid #2a85ff26;
  z-index: 0;
}
.app-bottom-nav a span {
  max-width: 85px;
}
.cart-wrapper {
  position: fixed;
  left: 50%;
  transform: translateX(-50%);
  bottom: calc(var(--tg-safe-bottom) + 90px);
  z-index: 45;
  min-width: 240px;
  max-width: calc(100vw - 32px);
  border: 1px solid #65acff4a;
