}
.wallet-connect,
.wallet-connect-placeholder {
  width: 144px;
  height: 48px;
  flex-shrink: 0;
}

.wallet-summary {
  font-size: 9px;
  color: #34d399;
  display: block;
  text-align: center;
  margin-top: 3px;
  white-space: nowrap;
}
.wallet-summary > span {
  color: var(--app-muted);
}
.bottom-sheet-dialog {
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--app-text);
  margin: auto auto 0;
  width: min(640px, 100vw);
  max-height: calc(
    var(--tg-viewport-height, 100svh) -
      max(24px, var(--tg-content-safe-area-inset-top, 0px))
  );
  overflow: visible;
}
.bottom-sheet-dialog::backdrop {
  background: #030912bb;
  backdrop-filter: blur(9px);
}
.bottom-sheet-surface {
  max-height: calc(var(--tg-viewport-height, 100svh) - 32px);
  overflow-y: auto;
  overscroll-behavior-y: contain;
  background: var(--app-panel);
  border: 1px solid #2a85ff30;
  border-radius: 30px 30px 0 0;
  padding-bottom: var(--tg-safe-bottom);
  position: relative;
  box-shadow: 0 -10px 50px #2a85ff12;
}
.sheet-drag-handle {
  height: 30px;
  display: grid;
  place-items: center;
  touch-action: none;
  cursor: grab;
  position: sticky;
  top: 0;
  z-index: 3;
  background: var(--app-panel);
  border-radius: 30px 30px 0 0;
}
.sheet-drag-handle > span {
  width: 42px;
  height: 4px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--app-text) 25%, transparent);
}
.bottom-sheet-surface .gift-close {
  top: 36px;
  right: 18px;
  width: 34px;
  height: 34px;
  background: var(--app-bg);
}
.bottom-sheet-surface .nft-dialog-content {
  display: block;
  padding: 8px 22px 26px;
}
.gift-modal-preview {
  max-width: 260px;
  margin: auto;
}
.gift-modal-details {
  padding-top: 8px;
}
.gift-modal-details h2 {
  font-size: 24px;
}
.gift-history {
  border-top: 1px solid #2a85ff16;
  padding: 12px 0;
  font-size: 11px;
}
.gift-history h3 {
  font-weight: 700;
  margin-bottom: 8px;
}
.gift-history a {
  display: block;
  padding: 8px 0;
  color: #2a85ff;
}
.gift-history p {
  color: var(--app-muted);
}
.modules-blue h1 {
  font-size: 34px;
  font-weight: 800;
  letter-spacing: -0.04em;
  margin: 16px 0;
}
.modules-blue > p {
  color: var(--app-muted);
  line-height: 1.8;
  font-size: 13px;
}
.module-card-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin: 24px 0;
}
.glass-module-card {
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  color: #2a85ff;
}
.glass-module-card h2 {
  font-size: 18px;
  color: var(--app-text);
}
.tour-page {
  --accent: #2a85ff;
}
.tour-page .eyebrow {
  color: #2a85ff;
}
.tour-intro h1 span,
.tour-controls .primary-button {
  color: #fff;
}
.tour-mode-label {
  display: none;
}
.admin-telegram-entry {
  max-width: 1080px;
  margin: 0 auto 20px;
  padding: 0 18px;
}
.app-loading {
  position: relative;
  height: 100svh;
  min-height: 100svh;
  display: grid;
  place-items: center;
  background: var(--app-bg, #0b0e14);
  color: var(--app-text, #f5f7fb);
  overflow: hidden;
  user-select: none;
}
.app-loading-video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: 0;
  pointer-events: none;
  filter: brightness(1.08) contrast(1.06);
}
.app-loading-overlay {
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, transparent 35%, rgba(7, 10, 20, 0.45) 80%, rgba(7, 10, 20, 0.85) 100%);
  pointer-events: none;
  z-index: 1;
}
.app-loading-aura {
  position: absolute;
  width: 320px;
  height: 320px;
  border-radius: 50%;
  pointer-events: none;
  background: radial-gradient(circle, color-mix(in srgb, var(--playful-blue, #568eff) 45%, transparent) 0%, color-mix(in srgb, var(--playful-violet, #a28aff) 30%, transparent) 45%, transparent 70%);
  filter: blur(55px);
  animation: legit-aura-pulse 3.5s ease-in-out infinite alternate;
}
.app-loading-content {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 24px;
}
.app-loading-brand {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
}
.app-loading-symbol {
  position: relative;
  width: 76px;
  height: 76px;
  display: grid;
  place-items: center;
  border-radius: 22px;
  background: radial-gradient(circle at 30% 20%, color-mix(in srgb, var(--playful-blue, #568eff) 25%, transparent), transparent 70%), linear-gradient(135deg, #13274f, #1b1a3d);
  border: 1px solid color-mix(in srgb, var(--playful-blue, #568eff) 45%, transparent);
  box-shadow: inset 0 1px 2px rgba(255,255,255,0.25), 0 10px 30px color-mix(in srgb, var(--playful-blue, #568eff) 35%, transparent);
  color: #fff;
}
.app-loading-symbol svg {
  color: var(--playful-aqua, #66decc);
  filter: drop-shadow(0 0 10px color-mix(in srgb, var(--playful-aqua, #66decc) 60%, transparent));
}
.app-loading-symbol .symbol-pulse {
  position: absolute;
  inset: -6px;
  border-radius: 26px;
  border: 1px solid color-mix(in srgb, var(--playful-blue, #568eff) 40%, transparent);
  animation: legit-symbol-ripple 2.4s ease-out infinite;
  pointer-events: none;
}
.app-loading-title {
  font-size: 21px;
  font-weight: 800;
  letter-spacing: 0.22em;
  margin: 0;
  background: linear-gradient(135deg, #ffffff 25%, var(--playful-blue, #568eff) 65%, var(--playful-violet, #a28aff) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 0 16px color-mix(in srgb, var(--playful-blue, #568eff) 40%, transparent));
}
.app-loading-track {
  width: 170px;
  height: 4px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
  position: relative;
  margin-bottom: 14px;
  box-shadow: inset 0 1px 2px rgba(0,0,0,0.4);
}
.app-loading-indicator {
  position: absolute;
  height: 100%;
  width: 45%;
  border-radius: 99px;
  background: linear-gradient(90deg, var(--playful-aqua, #66decc), var(--playful-blue, #568eff), var(--playful-violet, #a28aff));
  box-shadow: 0 0 12px var(--playful-blue, #568eff);
  animation: legit-track-glide 1.6s ease-in-out infinite;
}
.app-loading-status {
  font-size: 13px;
  color: var(--app-muted, #8e9bb5);
  margin: 0 0 20px 0;
  font-weight: 500;
  letter-spacing: 0.02em;
}
.app-loading-shield {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 5px 12px;
  border-radius: 99px;
  background: color-mix(in srgb, var(--playful-blue, #568eff) 10%, var(--app-bg, #0b0e14));
  border: 1px solid color-mix(in srgb, var(--playful-blue, #568eff) 22%, transparent);
  font-size: 11px;
  color: var(--app-muted, #8e9bb5);
  letter-spacing: 0.04em;
}
.app-loading-shield .shield-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #22c55e;
  box-shadow: 0 0 8px #22c55e;
  animation: legit-shield-blink 2s ease-in-out infinite;
}
@keyframes legit-aura-pulse {
  0% { transform: scale(0.92); opacity: 0.45; }
  100% { transform: scale(1.12); opacity: 0.85; }
}
@keyframes legit-symbol-ripple {
  0% { transform: scale(0.95); opacity: 0.8; }
  100% { transform: scale(1.22); opacity: 0; }
}
@keyframes legit-track-glide {
  0% { left: -45%; }
  100% { left: 100%; }
}
@keyframes legit-shield-blink {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.45; transform: scale(0.85); }
}
.desktop-preview {
