/* Minimal collectible market: SF Pro on Apple, bundled Inter elsewhere. */
:root {
  --app-bg: var(--tg-theme-bg-color, #151515);
  --app-panel: var(--tg-theme-secondary-bg-color, #222222);
}
body,
button,
input,
select,
textarea {
  font-family:
    "SF Pro Text",
    -apple-system,
    BlinkMacSystemFont,
    "Inter Variable",
    system-ui,
    sans-serif;
}
body,
.native-app,
.native-header,
.desktop-preview {
  background-image: none;
}
.native-header {
  box-shadow: none;
  backdrop-filter: none;
  background: var(--app-bg);
}
.native-main {
  padding-top: 12px;
}
.native-brand {
  font-weight: 600;
  letter-spacing: -0.025em;
}
.minimal-catalog {
  padding: 0;
}
.minimal-toolbar {
  background: var(--app-bg);
  position: sticky;
  top: 0;
  z-index: 5;
  padding: 0 0 8px;
}
.minimal-catalog .nft-controls {
  display: flex;
  gap: 8px;
  margin: 0;
}
.minimal-catalog .gift-search {
  min-width: 0;
  flex: 1;
  height: 44px;
  padding: 0 12px;
  border: 0;
  border-radius: 24px;
  background: var(--app-panel);
}
.minimal-catalog .gift-search input {
  font-size: 15px;
}
.minimal-catalog .minimal-tool {
  flex: 0 0 44px;
  width: 44px;
  height: 44px;
  padding: 0;
  display: grid;
  place-items: center;
  background: var(--app-panel);
  border: 0;
  border-radius: 50%;
}
.minimal-tool[aria-pressed="true"] {
  color: var(--brand-blue);
}
.minimal-filter-strip {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-top: 10px;
  scrollbar-width: none;
}
.minimal-filter {
  display: flex;
  align-items: center;
  gap: 5px;
  flex: 1 0 auto;
  background: var(--app-panel);
  border-radius: 22px;
  padding: 9px 12px;
  font-size: 13px;
}
.minimal-filter select {
  min-width: 20px;
  max-width: 100px;
  color: var(--app-muted);
  font-size: 12px;
  border: 0;
  background: transparent;
}
.minimal-filter:has(select:not([value=""])) {
  border: 0;
}
.minimal-advanced {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  padding-top: 12px;
}
.minimal-advanced label {
  font-size: 12px;
  color: var(--app-muted);
  display: grid;
  gap: 5px;
}
.minimal-advanced input,
.minimal-advanced select {
  width: 100%;
  min-width: 0;
  background: var(--app-panel);
  border: 1px solid var(--app-border);
  padding: 10px;
  border-radius: 12px;
  color: var(--app-text);
}
.minimal-catalog .nft-results-bar {
  font-size: 12px;
  margin: 4px 0 12px;
}
.minimal-catalog .nft-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
.minimal-catalog .nft-gift-card {
  background: var(--app-panel);
  border: 0;
  box-shadow: none;
  border-radius: 18px;
  transform: none;
  padding: 0;
  overflow: hidden;
  position: relative;
}
.minimal-catalog .nft-gift-card:hover {
  transform: none;
  box-shadow: none;
  border: 0;
}
.minimal-catalog .gift-preview {
  display: block;
  padding: 0;
  width: 100%;
  aspect-ratio: 1;
  background: transparent;
  border-radius: 16px;
  overflow: hidden;
}
.minimal-catalog .gift-preview::after {
  display: none;
}
.minimal-catalog .gift-preview img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  filter: none;
}
.minimal-catalog .gift-favorite {
  width: 29px;
  height: 29px;
  top: 9px;
  right: 9px;
  background: #0002;
  border: 0;
  color: #fff;
}
.minimal-catalog .gift-card-details {
  padding: 10px 12px 12px;
}
.minimal-catalog .gift-name,
button.gift-name {
  background: transparent !important;
  background-color: transparent !important;
  border: 0 !important;
  outline: none !important;
  box-shadow: none !important;
  color: var(--app-text) !important;
  display: block;
  width: 100%;
  font-size: 15px;
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: -0.025em;
  text-align: left;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  padding: 0;
  margin: 0;
  cursor: pointer;
}
.minimal-catalog .minimal-item-number {
  margin: 3px 0 11px;
  font-size: 13px;
  color: var(--app-muted);
}
.minimal-card-actions {
  display: flex;
  gap: 7px;
  align-items: center;
}
.minimal-price {
  flex: 1;
  min-width: 0;
  border-radius: 22px;
  background: var(--brand-blue);
  color: white;
  min-height: 33px;
  padding: 6px 8px;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}
.minimal-buy-icon {
  flex: 0 0 33px;
  height: 33px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--app-text) 8%, var(--app-panel));
  display: grid;
  place-items: center;
}
.bottom-sheet-surface {
  border: 0;
  background: var(--app-panel);
  box-shadow: none;
}
.minimal-sheet {
  padding: 4px 18px 22px;
}
.minimal-hero {
  position: relative;
  width: min(100%, 300px);
  aspect-ratio: 1;
  margin: 0 auto 18px;
  border-radius: 20px;
  overflow: hidden;
}
.minimal-hero > div:last-child {
  position: absolute;
  bottom: 13px;
  left: 17px;
  color: white;
  text-shadow: 0 1px 5px rgba(0, 0, 0, 0.8);
  background: transparent !important;
  border: 0 !important;
  padding: 0 !important;
}
.minimal-hero h2,
.minimal-confirm h2 {
  font-size: 24px;
  line-height: 1.2;
  font-weight: 600;
  letter-spacing: -0.04em;
  margin: 0 0 4px;
  color: white;
  background: transparent !important;
  border: 0 !important;
}
.minimal-hero p {
  margin: 0;
  font-size: 14px;
  color: rgba(255, 255, 255, 0.7);
  background: transparent !important;
  border: 0 !important;
}
.minimal-sheet .gift-attributes {
  display: block;
  margin: 16px 0;
  padding: 0;
  background: transparent;
  border: 0;
}
.minimal-sheet .gift-attributes > div {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 9px 0;
  border: 0;
  background: transparent;
}
.minimal-sheet dt {
  color: var(--app-muted);
  font-size: 14px;
}
.minimal-sheet dd {
  color: var(--brand-blue);
  font-weight: 500;
  font-size: 14px;
  text-align: right;
  overflow-wrap: anywhere;
}
.minimal-history {
  font-size: 13px;
  color: var(--app-muted);
  padding: 8px 0 15px;
}
.minimal-sheet-actions {
  display: grid;
  grid-template-columns: 1fr 1.5fr;
  gap: 10px;
  margin-top: 14px;
}
.minimal-sheet-actions button {
  min-height: 52px;
  border-radius: 14px;
  font-size: 15px;
  font-weight: 600;
  padding: 10px;
  box-shadow: none;
}
.minimal-sheet-actions small {
  display: block;
  font-size: 12px;
  font-weight: 400;
  margin-top: 3px;
}
.minimal-sheet .primary-button {
  background: var(--brand-blue);
  background-image: none;
}
.minimal-sheet .secondary-button {
  background: color-mix(in srgb, var(--app-text) 8%, var(--app-panel));
  border: 0;
}
.minimal-note {
  color: var(--app-muted);
  font-size: 13px;
  line-height: 1.5;
  margin: 12px 0;
}
.minimal-order-summary {
  display: flex;
  gap: 14px;
  align-items: center;
  background: var(--app-bg);
  border-radius: 16px;
  padding: 12px;
  margin: 18px 0;
}
.minimal-order-summary > div:first-child {
  width: 86px;
  height: 86px;
  flex: 0 0 86px;
}
.minimal-order-summary p {
  margin: 4px 0 8px;
  color: var(--app-muted);
  font-size: 13px;
}
.minimal-order-summary strong {
  font-size: 15px;
  font-weight: 600;
}
@media (max-width: 350px) {
  .minimal-catalog .gift-card-details {
    padding: 8px;
  }
  .minimal-price {
    font-size: 10px;
  }
  .minimal-catalog .gift-name {
    font-size: 14px;
  }
  .minimal-filter {
    padding: 8px;
