/* v32: real deposit NFT checkout */
.nft-mode-tabs{display:flex;gap:6px;padding:5px;border:1px solid var(--app-border,#ffffff18);border-radius:16px;margin:14px 0;background:var(--surface)}
.nft-mode-tabs button{min-height:44px;flex:1;border-radius:12px;background:transparent;font-weight:650;color:var(--muted)}
.nft-mode-tabs button.active{background:var(--tg-theme-button-color,#438bff);color:var(--tg-theme-button-text-color,#fff);box-shadow:0 4px 18px #438bff26}
.deposit-nft-checkout{display:grid;gap:14px;min-width:0;padding:16px 0}.deposit-nft-checkout h3{margin:0;font-size:20px}
.nft-recipient{display:block;overflow-wrap:anywhere;white-space:normal;font-size:12px;line-height:1.6;padding:12px;border:1px solid var(--app-border,#ffffff18);border-radius:12px;background:var(--surface)}
.nft-purchase-consent{display:flex;align-items:flex-start;gap:12px;font-size:13px;line-height:1.6;padding:12px 0;min-height:44px}
.nft-purchase-consent input{width:22px;height:22px;flex:0 0 22px;accent-color:#438bff;margin:3px 0 0}
.deposit-nft-checkout .secondary-button,.deposit-nft-checkout .primary-button{width:100%;text-align:center;justify-content:center;white-space:normal;min-height:46px}
.nft-admin-list{display:grid;gap:12px}.nft-admin-list article{padding:16px;border:1px solid #ffffff17;border-radius:14px;overflow-wrap:anywhere}.nft-admin-list code{font-size:11px;overflow-wrap:anywhere}

.minimal-confirm .minimal-order-summary{margin:10px 0;padding:10px;gap:12px;min-height:80px}
.minimal-confirm .minimal-order-summary>div:first-child{width:60px;height:60px;flex:0 0 60px}
.minimal-confirm .deposit-nft-checkout{gap:10px;padding:8px 0}
.minimal-confirm .deposit-nft-checkout .gift-attributes{margin:4px 0}
.minimal-confirm .deposit-nft-checkout .gift-attributes>div{padding:7px 0}
.minimal-confirm .deposit-nft-checkout dt{font-size:12px}
.minimal-confirm .nft-recipient{font-size:11px;line-height:1.5;padding:10px}
.minimal-confirm .nft-purchase-consent{font-size:12px;padding:6px 0}

