          data: {
            userId: user.id,
            walletId: wallet.id,
            orderId: order.id,
            kind: "PURCHASE",
            status: "POSTED",
            amount: total.neg().toString(),
            idempotencyKey: `purchase:${order.id}`,
            postedAt: new Date(),
          },
        });
