      throw new M_lib_commerce_core.ShopError("payment_transport", 503, true);
    }
    if (!r.ok) {
      await r.body?.cancel();
      throw new M_lib_commerce_core.ShopError("payment_provider", 503, true);
    }
    try {
      return await r.json();
    } catch {
      throw new M_lib_commerce_core.ShopError("payment_format", 503, true);
    }
  }
