      /(?:^|\/)\.(?:env|git|svn|hg)(?:[/.]|$)/.test(path) ||
      /(?:^|\/)(?:src|prisma|node_modules|backup|backups)(?:\/|$)/.test(path) ||
      /^\/_next\/server(?:\/|$)/.test(path) ||
      /\.(?:map|sql|sqlite|sqlite3|db|bak|old|zip|tar|gz|prisma)(?:\/|$)/.test(path) ||
