const bridgeLogTimes=new Map<string,number>();
function logBridge(action:string,reason:string,status?:number) {
 const key=action+":"+reason+":"+(status??0),now=Date.now();
 if(now-(bridgeLogTimes.get(key)??0)<60000)return;
 if(bridgeLogTimes.size>=128)bridgeLogTimes.delete(bridgeLogTimes.keys().next().value!);
 bridgeLogTimes.set(key,now);
 console.warn(JSON.stringify({event:"bridge.failure",action,reason,...(status?{upstreamStatus:status}:{})}));
}
// Read traffic gets a bounded, per-process budget. Financial/authentication limits remain durable.
export class ReadBudget {
 private entries=new Map<string,{attempts:number;expires:number}>();
 private nextSweep=0;
 constructor(private readonly capacity=20000){}
 get size(){return this.entries.size;}
 take(key:string,limit:number,windowMs:number,now=Date.now()) {
  if(now>=this.nextSweep){for(const [key,value] of this.entries)if(value.expires<=now)this.entries.delete(key);this.nextSweep=now+1000;}
  const entry=this.entries.get(key);
  if(!entry||entry.expires<=now){
   if(!entry&&this.entries.size>=this.capacity)return false;
   this.entries.set(key,{attempts:1,expires:now+windowMs});return true;
  }
  if(entry.attempts>=limit)return false;entry.attempts++;return true;
 }
}
export class InFlightReads {
 private pending=new Map<string,Promise<any>>();
 constructor(private readonly capacity=96){}
 get size(){return this.pending.size;}
 run<T>(key:string,load:()=>Promise<T>):Promise<T>{
  const existing=this.pending.get(key);if(existing)return existing;
  if(this.pending.size>=this.capacity)return Promise.reject(new M_lib_commerce_core_ShopError("bridge_busy",503));
  const task=Promise.resolve().then(load).finally(()=>this.pending.delete(key));
  this.pending.set(key,task);return task;
 }
}
