 activeBridgeRequests++;
 let upstreamStatus:number|undefined;
 try {
  const configuration=assessBridgeConfiguration(process.env);
  if(!configuration.ok)throw new M_lib_commerce_core_ShopError(configuration.code,503);
  const rawBase=(process.env.BOT_BRIDGE_URL||"").trim().replace(/\/(uk|ru|en)\/?$/i,"");
