  const response=await fetch(new URL(path,base.toString().replace(/\/?$/,"/")),{method:"POST",headers:{Authorization:`Bearer ${process.env.BOT_BRIDGE_SECRET}`,"Content-Type":"application/json","Bypass-Tunnel-Reminder":"true","bypass-tunnel-reminder":"true","ngrok-skip-browser-warning":"1","User-Agent":"localtunnel"},body:JSON.stringify(data),cache:"no-store",redirect:"error",signal:AbortSignal.timeout(timeoutMs)});
