  if(!response.headers.get("content-type")?.includes("application/json"))throw new M_lib_commerce_core_ShopError(response.status===404?"bridge_endpoint_missing":"bridge_invalid_response",503);
  let result;try{result=await response.json();}catch{throw new M_lib_commerce_core_ShopError("bridge_invalid_response",503);}
  if(!result||typeof result!=="object"||Array.isArray(result))throw new M_lib_commerce_core_ShopError("bridge_invalid_response",503);
  const allowedErrors=new Set(["invalid_request","forbidden","invalid_product","item_unavailable","invalid_price","invalid_balance","insufficient_balance","price_changed","confirmation_required","quote_expired","quote_not_found","quote_mismatch","invalid_order","order_not_found","provider_unavailable","provider_invalid_response","provider_busy","marketapp_not_configured","marketapp_free_plan","chain_unavailable","smm_not_configured","ledger_precision_required","ledger_not_ready","bridge_unavailable","invalid_address","invalid_chain_method","invalid_transaction","invalid_provider_operation","invalid_filter","invalid_category","invalid_locale","action_not_configured","not_found","invalid_amount","crypto_amount_limit","listing_selection_required","withdrawals_disabled","wallet_proof_required","request_mismatch","crypto_request_pending","transaction_already_used","withdrawal_in_review","withdrawable_balance_required","nft_not_configured","nft_signer_not_configured","nft_signer_address_mismatch","nft_store_liquidity","nft_delivery_review","nft_history_incomplete","unsupported_nft_sale","nft_catalog_config_invalid","nft_executor_missing","nft_executor_unavailable","nft_order_limit","nft_order_pending"]);
  if(!response.ok)throw new M_lib_commerce_core_ShopError(typeof result.error==="string"&&allowedErrors.has(result.error)?result.error:"bot_unavailable",[400,402,403,404,409,429,503].includes(response.status)?response.status:503);
  return result;
 }catch(e){
  const error=e instanceof M_lib_commerce_core_ShopError?e:new M_lib_commerce_core_ShopError(e instanceof Error&&["TimeoutError","AbortError"].includes(e.name)?"bridge_timeout":"bridge_unreachable",503);
  logBridge(path,error.code,upstreamStatus);throw error;
 }finally{activeBridgeRequests--;}
}
