// Decode provider BOCs rather than trusting webhook fields, comments or client hashes.
export function cryptoReceipt(raw:unknown,expected:{source:string;destination:string;memo:string;minNano:string;created:number;exact?:boolean},now=Math.floor(Date.now()/1000)){
 try{
  if(typeof raw!=="string"||raw.length>160000)return null;
  const cell=M_lib_nft_i5.fromBase64(raw),tx=nftLoadTransaction(cell.beginParse()),d=tx.description,msg=tx.inMessage;
  const destination=M_lib_nft_i4.parse(expected.destination);
  if(tx.address!==BigInt("0x"+destination.hash.toString("hex"))||tx.now<expected.created-60||tx.now>now-60||d.type!=="generic"||d.aborted||d.destroyed||d.bouncePhase||!d.creditPhase||d.computePhase.type!=="vm"||!d.computePhase.success||![0,1].includes(d.computePhase.exitCode)||(d.actionPhase&&(!d.actionPhase.success||d.actionPhase.resultCode!==0)))return null;
  if(!msg||msg.info.type!=="internal"||msg.info.bounced||msg.info.src.toRawString()!==expected.source||!msg.info.dest.equals(destination)||msg.info.value.coins<BigInt(expected.minNano)||d.creditPhase.credit.coins<BigInt(expected.minNano))return null;
  if(expected.exact&&msg.info.value.coins!==BigInt(expected.minNano))return null;
  const body=msg.body.beginParse();if(body.loadUint(32)!==0||body.loadStringTail()!==expected.memo)return null;
  return {txHash:cell.hash().toString("hex"),amountNano:msg.info.value.coins.toString(),created:tx.now};
 }catch{return null;}
}
async function cryptoHistory(address:string,oldest:number,start?:{lt?:unknown;hash?:unknown}){
 let lt:string|undefined,hash:string|undefined;
 if(start?.lt||start?.hash){if(typeof start.lt!=="string"||!/^\d{1,22}$/.test(start.lt)||typeof start.hash!=="string"||! /^(?:[0-9a-fA-F]{64}|[A-Za-z0-9+/]{43}=)$/.test(start.hash))throw new M_lib_commerce_core_ShopError("invalid_transaction");lt=start.lt;hash=/^[0-9a-fA-F]{64}$/.test(start.hash)?Buffer.from(start.hash,"hex").toString("base64"):start.hash;}const result:unknown[]=[];
 for(let page=0;page<5;page++){
  const value=await ecosystemProviderRequest("chain-read",{method:"getTransactions",params:{address,limit:100,...(lt?{lt,hash}:{})}});
  const batch=value.result;if(!Array.isArray(batch))throw new M_lib_commerce_core_ShopError("chain_unavailable",503);
  for(const tx of batch)if(tx&&typeof tx==="object"&&typeof tx.data==="string")result.push(tx.data);
