export type EcosystemCatalogData = {category:EcosystemCategory;groups:Record<string,string>;items:EcosystemProduct[];updatedAt:string;browseAccounts?:boolean;groupGames?:Record<string,number>;page?:number;hasNext?:boolean};
export function ecosystemPayload(category:string,id:string,nonce:string):string {
  if(!ecosystemCategories.includes(category as EcosystemCategory) || !/^[a-zA-Z0-9_]{1,48}$/.test(id) || !/^[a-z0-9]{4}$/.test(nonce))throw Error("invalid_product");
