  if(code.length>64)throw Error("order_link_too_long");
  return code;
}

export function validateEcosystemCatalog(value:unknown):EcosystemCatalogData {
 if(!value||typeof value!=="object")throw Error("invalid_catalog");
 const d=value as EcosystemCatalogData;
 if(!ecosystemCategories.includes(d.category)||!Array.isArray(d.items)||d.items.length>500||!d.groups||typeof d.groups!=="object"||Array.isArray(d.groups)||typeof d.updatedAt!=="string"||!Number.isFinite(Date.parse(d.updatedAt)))throw Error("invalid_catalog");
 if(Object.entries(d.groups).some(([key,label])=>key.length>80||typeof label!=="string"||label.length>2000))throw Error("invalid_catalog");
 if(d.browseAccounts!==undefined&&(typeof d.browseAccounts!=="boolean"||!Number.isSafeInteger(d.page)||d.page!<1||d.page!>100||typeof d.hasNext!=="boolean"))throw Error("invalid_catalog");
 if(d.groupGames!==undefined&&(!d.groupGames||typeof d.groupGames!=="object"||Array.isArray(d.groupGames)||Object.entries(d.groupGames).some(([key,id])=>!(key in d.groups)||!Number.isSafeInteger(id)||id<1||id>999999999)))throw Error("invalid_catalog");
 const ids=new Set<string>();
 for(const p of d.items){if(!p||!(/^[a-zA-Z0-9_]{1,48}$/.test(p.id))||ids.has(p.id)||typeof p.name!=="string"||p.name.length>2000||typeof p.description!=="string"||p.description.length>2000||typeof p.group!=="string"||typeof p.priceUAH!=="string"||!/^\d{1,12}\.\d{2}$/.test(p.priceUAH))throw Error("invalid_catalog");if(p.listingId!==undefined&&(!/^[1-9][0-9]{0,11}$/.test(p.listingId)||p.id!=="lot_"+p.listingId||!["steam","telegram","minecraft"].includes(p.provider??"")))throw Error("invalid_catalog");if(p.steamAppId!==undefined&&(!Number.isSafeInteger(p.steamAppId)||p.steamAppId<1||p.steamAppId>999999999))throw Error("invalid_catalog");ids.add(p.id);}
 return d;
}

