export type BridgeConfigurationCode="ready"|"bridge_url_missing"|"bridge_url_invalid"|"bridge_secret_missing"|"bridge_secret_invalid"|"bridge_self_reference";
export function assessBridgeConfiguration(env:Record<string,string|undefined>):{ok:boolean;code:BridgeConfigurationCode} {
 if(!env.BOT_BRIDGE_URL?.trim())return {ok:false,code:"bridge_url_missing"};
 const raw=(env.BOT_BRIDGE_URL||"").trim().replace(/\/(uk|ru|en)\/?$/i,"");
 let url:URL;try{url=new URL(raw);}catch{return {ok:false,code:"bridge_url_invalid"};}
 if((url.protocol!=="https:" && !(url.protocol==="http:" && (url.hostname==="127.0.0.1"||url.hostname==="localhost"))) ||!url.hostname||url.username||url.password||url.search||url.hash)return {ok:false,code:"bridge_url_invalid"};
 const ownHosts=new Set<string>();
 for(const raw of [env.NEXT_PUBLIC_SITE_URL,env.NGROK_URL,env.TUNNEL_URL,env.RAILWAY_PUBLIC_DOMAIN?"https://"+env.RAILWAY_PUBLIC_DOMAIN:undefined])try{if(raw)ownHosts.add(new URL(raw).host.toLowerCase());}catch{}
 if(ownHosts.has(url.host.toLowerCase()))return {ok:false,code:"bridge_self_reference"};
 if(!env.BOT_BRIDGE_SECRET)return {ok:false,code:"bridge_secret_missing"};
 if(!/^[A-Za-z0-9_-]{32,256}$/.test(env.BOT_BRIDGE_SECRET))return {ok:false,code:"bridge_secret_invalid"};
 return {ok:true,code:"ready"};
}

// Only deployment-controlled values may define the CSRF origin; never request headers.
export function isNgrokHost(host: string | null | undefined): boolean {
 if (!host) return false;
 const h = host.split(":")[0].toLowerCase();
 return (
  h.endsWith(".ngrok-free.app") ||
  h.endsWith(".ngrok.app") ||
  h.endsWith(".ngrok.io") ||
  h.endsWith(".ngrok-free.dev") ||
  h === "ngrok.io"
 );
}

export function isNgrokOrigin(origin: string | null | undefined): boolean {
 if (!origin) return false;
 try {
  const u = new URL(origin);
  if (u.protocol !== "https:" && u.protocol !== "http:") return false;
  return isNgrokHost(u.hostname);
 } catch {
  return false;
 }
}

export function trustedAppOrigin(env:Record<string,string|undefined>):string|null {
 let raw=env.NEXT_PUBLIC_SITE_URL?.trim() || env.NGROK_URL?.trim() || env.TUNNEL_URL?.trim();
 if(!raw){
  const host=env.RAILWAY_PUBLIC_DOMAIN?.trim();
  if(!host||!/^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/i.test(host))return null;
  raw="https://"+host;
 }
 try{
  const url=new URL(raw);
  if(url.username||url.password||!["http:","https:"].includes(url.protocol)||(env.NODE_ENV==="production"&&url.protocol!=="https:"&&!["localhost","127.0.0.1"].includes(url.hostname)))return null;
  return url.origin;
 }catch{return null;}
}
