    function extractCredentialFields(raw: string) {
      const clean = raw.replace(/<[^>]+>/g, " ").replace(/&[a-z0-9#]+;/gi, " ").replace(/\s+/g, " ").trim();
      let login = "";
      let password = "";
      let additional = "";

      const phoneMatch = raw.match(/(?:Телефон|Phone|Login|Логін|Акаунт|Account):\s*<code>([^<]+)<\/code>/i) ||
                         raw.match(/(?:Телефон|Phone|Login|Логін|Акаунт|Account):\s*([^\n\r<]+)/i);
      if (phoneMatch) login = phoneMatch[1].trim();

      const passMatch = raw.match(/(?:Пароль|Password|Pass):\s*<code>([^<]+)<\/code>/i) ||
                        raw.match(/(?:Пароль|Password|Pass):\s*([^\n\r<]+)/i);
      if (passMatch) password = passMatch[1].trim();

      const codeMatch = raw.match(/(?:Код|Code|2FA|Guard):\s*<code>([^<]+)<\/code>/i) ||
                        raw.match(/(?:Код|Code|2FA|Guard):\s*([^\n\r<]+)/i);
      if (codeMatch) additional = codeMatch[1].trim();

      if (!login && !password && clean.includes(":") && !clean.includes("\n")) {
        const parts = clean.split(":");
        if (parts.length >= 2) {
          login = parts[0].trim();
          password = parts[1].trim();
          if (parts.length > 2) additional = parts.slice(2).join(":").trim();
        }
      }

      return {login, password, additional, rawClean: clean};
    }

