          <div className="wallet-sheet-actions"><button className="secondary-button" onClick={()=>{
            void Promise.resolve().then(()=>navigator.clipboard.writeText(address)).then(()=>{setCopied(true);M_hooks_useTelegramWebApp.haptic("success");}).catch(()=>setError(locale==="uk"?"Не вдалося скопіювати адресу":locale==="ru"?"Не удалось скопировать адрес":"Could not copy address"));
          }}>{copied?<Check size={18}/>:<Copy size={18}/>}<span>{copied?t.copied:t.copyAddress}</span></button>
          <button className="wallet-disconnect" disabled={busy} onClick={()=>{
